public sealed partial class CityInterface {
 string _tradeResource="food",_tradeSide="buy",_tradeAmount="12",_tradeLimit="";
 void MarketPage(){
  if(_pageContext=="food"||_pageContext=="material"||_pageContext=="goods")_tradeResource=_pageContext;
  var columns=WorkspaceColumns("Market quotes orders editor",.24f,.42f,.34f);var quotes=columns[0];var orders=columns[1];var editor=columns[2];Label(quotes,"共享市场报价",23,Blue);
  foreach(var resource in new[]{"food","material","goods"}){var r=resource;var q=Market.quote(G,r);var line=CompactTaskCard(quotes,"Market quote "+r);Button(line,(_tradeResource==r?"● ":"")+Resource(r),()=>{_tradeResource=r;_tradeLimit="";_pageContext="";RenderPage();},_tradeResource==r);Metric(line,"买入",F(q.Get("buy_price",0).Double,3));Metric(line,"卖出",F(q.Get("sell_price",0).Double,3));Label(line,"当前库存 "+F(G.inventory_total(r)),15,Muted);}
  Label(quotes,"真实在线货运",20,Blue);Label(quotes,F(Market._total_capacity(G))+" 单位 / 现实在线小时",18);var ledger=S["block"].Get("trade_ledger",V.Arr());if(ledger.Count!=0)Meter(quotes,"最近周期使用",ledger[-1]["used_capacity"].Double,ledger[-1]["capacity"].Double," 单位",Blue);Fold(quotes,"运力结算完整来源",c=>Raw(c,ledger));
  Label(orders,"订单与成交",24,Blue);Label(orders,"订单按稳定次序共享真实在线运力。",16,Muted);var allOrders=S["block"]["trade_orders"];if(allOrders.Count==0)Label(orders,"尚无订单，右侧可创建限价订单。",18,Muted);
  foreach(var item in allOrders.Reverse()){var id=item["id"].Text;var line=CompactTaskCard(orders,"Order "+id);var status=item["status"].Text;Label(line,Resource(item["resource"].Text)+" · "+(item["side"].Text=="buy"?"买入":"卖出")+" · "+V.Map("open","等待成交","partial","部分成交","filled","全部成交","cancelled","已取消").Get(status,status).Text,19);Label(line,"剩余 "+F(item["remaining"].Double)+" / "+F(item["amount"].Double)+" · 限价 "+F(item["limit_price"].Double,3),17,Gold);if(status=="open"||status=="partial")Button(line,"取消订单",()=>Command(g=>Market.cancel(g,id)));Fold(line,"订单凭据",c=>Raw(c,item));}
  Fold(orders,"真实成交记录",c=>{foreach(var trade in S["block"]["trade_history"].Reverse().Take(100)){Label(c,Resource(trade["resource"].Text)+" · "+(trade["side"].Text=="buy"?"买入":"卖出")+" "+F(trade["amount"].Double,3)+" × "+F(trade["unit_price"].Double,3)+" · 通货 "+Signed(trade["currency_delta"].Double),16);Fold(c,"运力提供来源与成交凭据",raw=>Raw(raw,trade));}});
  Label(editor,"创建限价订单",24,Gold);Label(editor,Resource(_tradeResource),22,Blue);var sides=Row(editor,"Trade side",46*TextScale);Button(sides,(_tradeSide=="buy"?"✓ ":"")+"买入",()=>{_tradeSide="buy";_tradeLimit="";RenderPage();});Button(sides,(_tradeSide=="sell"?"✓ ":"")+"卖出",()=>{_tradeSide="sell";_tradeLimit="";RenderPage();});
  var quote=Market.quote(G,_tradeResource);var price=quote.Get(_tradeSide+"_price",0).Double;if(_tradeLimit=="")_tradeLimit=price.ToString("F3",CultureInfo.InvariantCulture);Metric(editor,"当前单位报价",F(price,3));Label(editor,_tradeSide=="buy"?"买价不高于限价才成交":"卖价不低于限价才成交",17,Gold);Label(editor,"数量",16,Muted);var amount=InputBox(editor,_tradeAmount,"输入正数量");amount.onValueChanged.AddListener(v=>_tradeAmount=v);Label(editor,"每单位限价（可为负）",16,Muted);var limit=InputBox(editor,_tradeLimit,"输入限价");limit.onValueChanged.AddListener(v=>_tradeLimit=v);
  Label(editor,price<0?(_tradeSide=="buy"?"当前负买价：接收资源时收到通货，仍受仓容和运力限制。":"当前负卖价：外运资源时支付处置通货，余额不足只成交可负担部分。"):(_tradeSide=="buy"?"买入支付通货，需要真实空仓容。":"卖出收到通货，真实扣除库存。"),17,Muted);Label(editor,"等待限价、仓容、库存、现金或共享运力时，订单保留。",16,Muted);
  WorkspaceActions("提交"+(_tradeSide=="buy"?"买入":"卖出")+Resource(_tradeResource)+"限价订单",()=>{if(!double.TryParse(_tradeAmount,NumberStyles.Float,CultureInfo.InvariantCulture,out var quantity)||!double.TryParse(_tradeLimit,NumberStyles.Float,CultureInfo.InvariantCulture,out var limitPrice)){ShowMessage("请输入有效数量与限价。");return;}Command(g=>Market.order(g,_tradeResource,_tradeSide,quantity,limitPrice));},Market._total_capacity(G)<=.000001);WorkspaceActions("资源与财政账目",()=>Navigate("resources",_tradeResource));WorkspaceHint("外部市场按真实在线时间结算，本地加速不扩大运力。");
 }
 string _policySlot="Tax";
 string _policyChoice="";
 void PoliciesPage(){
  var columns=WorkspaceColumns("Policy current candidate comparison",.43f,.57f);var currentColumn=columns[0];var candidateColumn=columns[1];Label(currentColumn,"政策类别",21,Muted);
  foreach(var slotValue in new[]{"Tax","Labor","Environment","Procurement","Land"}){var slot=slotValue;Button(currentColumn,(_policySlot==slot?"● ":"")+V.Map("Tax","税收","Labor","用工","Environment","环境","Procurement","采购","Land","土地").Get(slot,slot).Text,()=>{if(_comparisonValid)ClearComparison();_policySlot=slot;_policyChoice="";RenderPage();},_policySlot==slot);}
  var currentId=S["block"]["policies"].Get(_policySlot,"").Text;var current=currentId!=""&&G.c.policies.Has(currentId)?G.c.policies[currentId]:V.Map();var baseline=_planner.snapshot(G);Label(currentColumn,"当前采用",23,Green);Label(currentColumn,current.Get("name","本槽未采用政策").Text,22);Label(currentColumn,current.Get("summary","").Text,17,Muted);Metric(currentColumn,"不更换 · 下一周期经营",F(baseline["metrics"].Get("cashflow",0).Double)+" /月");Button(currentColumn,"地图 · 现状预测",()=>{_baseline=baseline;_proposal=V.Map();ShowForecastMap("baseline",baseline);});if(current.Count>0)Fold(currentColumn,"当前政策完整规则",c=>Raw(c,current));
  var candidates=Rules.ids(G.c.policies).Select(x=>x.Text).Where(id=>G.c.policies[id]["slot"].Text==_policySlot).ToArray();if(!candidates.Contains(_policyChoice))_policyChoice=candidates.FirstOrDefault(id=>id!=currentId)??candidates.FirstOrDefault()??"";Label(candidateColumn,"候选政策",23,Blue);foreach(var candidateId in candidates){var id=candidateId;Button(candidateColumn,(_policyChoice==id?"● ":"")+G.c.policies[id]["name"].Text+(id==currentId?" · 当前":""),()=>{_policyChoice=id;if(_comparisonValid)ClearComparison();RenderPage();},_policyChoice==id);}
  if(_policyChoice=="")return;var selected=_policyChoice;var policy=G.c.policies[selected];var preview=_planner.policy(G,selected);var isCurrent=currentId==selected;Label(candidateColumn,policy["name"].Text,25,Gold);Label(candidateColumn,policy.Get("summary","").Text,18,Muted);Metric(candidateColumn,"更换费用",F(G.c.balance["policy_switch_price"].Double,0)+" 通货");if(preview.Get("ok",false).Bool){Metric(candidateColumn,"采用后 · 下一周期经营",F(preview["cashflow"].Double)+" /月");Metric(candidateColumn,"相对不更换",Signed(preview["delta"].Double)+" /月","两边均为同一步真实结算。",preview["delta"].Double>=0?Green:Gold);Button(candidateColumn,"地图 · 采用后预测",()=>{_baseline=baseline;_proposal=preview;PublishComparison();ShowForecastMap("proposal",preview["map_snapshot"]);});}else Label(candidateColumn,preview.Get("error","预测不可用").Text,17,Gold);Fold(candidateColumn,"候选政策完整规则",c=>Raw(c,policy));
  var version=_planner.version(G);WorkspaceActions(isCurrent?"此政策已采用":"支付并更换政策",()=>{if(version!=_planner.version(G)){RenderPage();ShowMessage("城市已变化，预测已刷新，请重新核对。");return;}Command(g=>g.switch_policy(selected));},isCurrent||!preview.Get("ok",false).Bool);WorkspaceHint("已选「"+policy["name"].Text+"」 · "+(isCurrent?"当前已采用，无本次支出":"更换即付 "+F(G.c.balance["policy_switch_price"].Double,0)+" 通货"));
 }
 void Impact(Transform parent,V baseline,V proposal){var card=Card(parent,"建设影响 · 同一步下一结算","月率、当前库存、住房容量、电力能力与污染分别表示，不能合成一个分数。",Blue);var world=proposal["world"];foreach(var resource in new[]{"food","material","goods"}){var before=baseline["metrics"].Get("flows",V.Map()).Get(resource,0).Double;var after=world.Get("flows",V.Map()).Get(resource,0).Double;Label(card,Resource(resource)+"净流量",19,Ink);Metric(card,"不建设",Signed(before)+" /月");Metric(card,"建成后",Signed(after)+" /月","",after>=before?Green:Gold);Meter(card,"当前库存（非预测库存）",G.inventory_total(resource),G.stock_cap(resource)," 单位",Blue);if(after<-.000001)Label(card,"当前库存 / 预测净消耗 ≈ "+F(G.inventory_total(resource)/-after)+"月；仅供参考，局部可达性与后续贸易会改变结果。",14,Muted);}
  Metric(card,"全城电力供给变化",Signed(proposal["energy_supply"].Double)+" 能力");Metric(card,"全城电力需求变化",Signed(proposal["energy_demand"].Double)+" 能力");Metric(card,"住房容量变化",Signed(proposal["housing"].Double)+" 人");Metric(card,"经营净额变化",Signed(proposal["cashflow"].Double)+" /月");Metric(card,"暴露上升的现有居民",F(proposal["harmed"].Double,0)+" 人","污染增加超过 0.015 的现有住户。",Gold);Fold(card,"投入、服务、竞争与完整规则来源",c=>{foreach(var resource in proposal["inputs"].Keys)Metric(c,"新增投入 · "+Resource(resource),F(proposal["inputs"][resource].Double,3)+" /月");foreach(var kind in proposal["added_service"].Keys)Metric(c,Service(kind)+"覆盖变化",Signed(proposal["added_service"][kind].Double)+" 人");foreach(var item in proposal["affected"])Label(c,G.project_name(item["id"].Text)+" 运行率变化 "+Signed(item["delta"].Double*100)+"个百分点",15,Gold);Raw(c,proposal["trace"]);});}
}
